  const memoryVault=document.createElement('article');memoryVault.className='card memory-vault';memoryVault.innerHTML='<header><div><span class="personal-kicker">PERSISTENT · MIT HERKUNFT</span><h2>Deine Memory-Einträge</h2><p class="personal-note">Jeder Eintrag zeigt Herkunft, Schutzklasse und optionales Ablaufdatum. Vergessen löscht nur diesen Eintrag.</p></div><span id="memory-count" class="badge">0 EINTRÄGE</span></header><form id="memory-form" class="memory-form"><label>Was soll '+agentName+' behalten?<input name="content" maxlength="1200" required placeholder="Zum Beispiel: Ich mag kurze Antworten."></label><label>Bereich<select name="area"><option value="communication">Kommunikation</option><option value="rhythm">Tagesrhythmus</option><option value="people-places">Menschen und Orte</option><option value="interests">Interessen</option><option value="home">Zuhause</option><option value="health">Gesundheit</option></select></label><label>Schutzklasse<select name="sensitivity"><option value="PRIVATE">Privat</option><option value="FAMILY">Familie</option><option value="FINANCIAL">Finanzen</option><option value="HEALTH">Gesundheit</option></select></label><label>Ablaufdatum<input name="expiresAt" type="date"></label><button type="submit">Merken</button></form><input id="memory-search" class="memory-search" type="search" placeholder="Memory durchsuchen …" aria-label="Memory durchsuchen"><div id="memory-entry-list" class="memory-entry-list"><div class="memory-empty">Memory wird geladen …</div></div>';memory.querySelector('.page-title').after(memoryVault);
