  const setupDialog=document.createElement('dialog');setupDialog.className='personal-setup';setupDialog.innerHTML='<div class="setup-panel"><header class="setup-head"><div><span id="setup-status" class="badge"></span><h2 id="setup-title"></h2></div><button class="setup-close" type="button" aria-label="Dialog schließen">×</button></header><div class="setup-body"><p id="setup-note" class="personal-note"></p><h3>Einrichtung</h3><ol id="setup-steps" class="setup-steps"></ol><h3>Erlaubte Bereiche</h3><div id="setup-permissions" class="setup-permissions"></div><h3>Privatsphäre</h3><div id="setup-privacy" class="setup-privacy"></div><div class="setup-actions"><button class="setup-disable" type="button">Deaktivieren</button><button class="setup-close" type="button">Schließen</button><button class="setup-save" type="button">Vorbereiten</button></div></div></div>';document.body.append(setupDialog);
  function renderConnectorStates(){const cards=[...document.querySelectorAll('#tools .personal-module')];cards.forEach((card,index)=>{const id=connectorIds[index],state=connectorState.get(id),badge=card.querySelector('.badge'),button=card.querySelector('button');if(state?.status==='CONNECTED'){badge.textContent='LIVE';button.textContent='Verbindung verwalten';}else if(state?.status==='PREPARED'){badge.textContent='VORBEREITET';button.textContent='Freigaben verwalten';}else{badge.textContent=connectorSetup[id]?.[1]||'SETUP';button.textContent='Einrichtung ansehen';}});const prepared=[...connectorState.values()].filter(item=>item.status==='PREPARED').length,connected=[...connectorState.values()].filter(item=>item.status==='CONNECTED').length;let summary=tools.querySelector('.connector-summary');if(!summary){summary=document.createElement('div');summary.className='connector-summary';tools.querySelector('.personal-section-grid')?.before(summary);}summary.innerHTML='<span><b>'+connected+'</b> LIVE</span><span><b>'+prepared+'</b> VORBEREITET</span><span><b>'+(connectorIds.length-connected-prepared)+'</b> AUS</span><span>Freigaben werden pro Instanz gespeichert</span>';const dayNotes=command.querySelectorAll('.day-item small');if(dayNotes[0])dayNotes[0].textContent=connectorState.get('calendar')?.status==='CONNECTED'?'Kalender ist verbunden':connectorState.get('calendar')?.status==='PREPARED'?'Kalender vorbereitet · Konto fehlt':'Kalender noch nicht verbunden';if(dayNotes[1])dayNotes[1].textContent=connectorState.get('home')?.status==='CONNECTED'?'Home Assistant ist verbunden':connectorState.get('home')?.status==='PREPARED'?'Home Assistant vorbereitet · Token fehlt':'Home Assistant wartet auf Verbindung';}
  async function loadConnectorStates(){try{const response=await fetch('/agentone/personal/connectors',{headers:{accept:'application/json'}});if(!response.ok)throw new Error('HTTP '+response.status);const payload=await response.json();for(const item of payload.connectors||[])connectorState.set(item.id,item);renderConnectorStates();}catch{renderConnectorStates();}}
  async function saveConnectorState(status){const permissions=[...setupDialog.querySelectorAll('#setup-permissions input:checked')].map(input=>input.value);const response=await fetch('/agentone/personal/connectors',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({id:activeConnector,status,permissions})});if(!response.ok)throw new Error('Status konnte nicht gespeichert werden');const payload=await response.json();connectorState.set(activeConnector,payload.connector);renderConnectorStates();setupDialog.close();}
  function openConnectorSetup(id){const data=connectorSetup[id];if(!data)return;activeConnector=id;const current=connectorState.get(id);setupDialog.querySelector('#setup-title').textContent=data[0];setupDialog.querySelector('#setup-status').textContent=current?.status||data[1];setupDialog.querySelector('#setup-note').textContent=current?.status==='PREPARED'?'Freigaben sind gespeichert. Für LIVE fehlt noch die eigentliche Konto- oder Geräteverbindung.':'Dieser Connector ist noch nicht mit einem Konto oder Gerät verbunden.';const steps=setupDialog.querySelector('#setup-steps');steps.replaceChildren(...data[2].split('. ').map(text=>{const li=document.createElement('li');li.textContent=text.replace(/\.$/,'')+'.';return li;}));const permissions=setupDialog.querySelector('#setup-permissions'),hasStoredPermissions=Array.isArray(current?.permissions)&&current.permissions.length>0;permissions.replaceChildren(...(connectorPermissions[id]||[]).map(([value,label])=>{const row=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=value;input.checked=current?.permissions?.includes(value)||(!hasStoredPermissions&&!safeMode&&isGuenni);row.append(input,document.createTextNode(label));return row;}));setupDialog.querySelector('#setup-privacy').textContent=data[3]+(!safeMode&&isGuenni?' Günni VOLLGAS: Alle angebotenen Bereiche sind für den Test vorausgewählt.':'');setupDialog.showModal();}
